AMOUNT_MEAN = 88.35
AMOUNT_STD  = 250.12


def prepare_input(amount: float) -> np.ndarray:
    closest = min(TRANSACTIONS, key=lambda x: abs(x['amount'] - amount))
    features = list(closest['v']) + [(amount - AMOUNT_MEAN) / AMOUNT_STD]
    return np.array([features])


def get_prediction(amount: float, time: int) -> tuple:
    input_data = prepare_input(amount)
    probability = float(model.predict(input_data)[0][0])
    result = 'fraud' if probability >= 0.5 else 'safe'
    return result, round(probability, 4)
